window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2927b70a15a43c20"]={"versions": [{"id": "FIG-2927b70a15a43c20", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 1</code> genau eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für alle Diagnosefähigkeiten.\n<ul class=\"fig-list\"><li><code>audience : DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement : DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel : PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType : DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength : PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess : DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>didNumber : PositiveInteger [0..1]</code>: 16-Bit DID-Nummer.\n</li><li><code>fixedLength : Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle : DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType : DiagnosticRoutineTypeEnum</code> (Kardinalität 1): Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li><li><code>ridNumber : PositiveInteger [0..1]</code>: 16-Bit Routine-Identifier (RID).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>didNumber : PositiveInteger [0..1]</code>: 16-Bit DID für die E/A-Steuerung.\n</li><li><code>freezeCurrentStateSupported : Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported : Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported : Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Assoziation zu <code>DiagnosticValueNeeds</code>, um den aktuellen Istwert der E/A-Schnittstelle über ein DID-Value-Modell rücklesbar zu machen.\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycleNeeds</code></strong>: Deklariert Betriebszyklen für die Entprellung und Alterung im Dem.\n<ul class=\"fig-list\"><li><code>operationCycle : OperationCycleTypeEnum</code>: Zyklustyp (<code>ignition</code>, <code>obdDcy</code>, <code>warmup</code>, <code>power</code>, <code>time</code>, <code>other</code>).\n</li><li><code>operationCycleAutomaticEnd : Boolean</code>: Automatisches Zyklusende durch BSW.\n</li><li><code>operationCycleAutostart : Boolean</code>: Automatischer Zyklusstart bei Initialisierung.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Deklaration dedizierter Sicherheitsanforderungen (Seed/Key-Mechanismen).\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: <code>{development, manufacturing, afterSales, supplier, aftermarket}</code>\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: <code>{readOnly, readWrite, writeOnly}</code>\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: <code>{synchronous, asynchronous}</code>\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: <code>{processingStyleSynchronous, processingStyleAsynchronous}</code>\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: <code>{requestCallbackTypeManufacturer, requestCallbackTypeSupplier}</code>\n</li><li><strong><code>OperationCycleTypeEnum</code></strong>: <code>{ignition, obdDcy, warmup, power, time, other}</code>\n</li><li><strong><code>ObdRatioConnectionKindEnum</code></strong>: <code>{apiUse, observer}</code> (OBD-spezifische IUMPR-Verbindungsarten)\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}, {"id": "FIG-ff3df9b5a95f3967", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 1</code> genau eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für diagnosebezogene Servicebedarfe.\n<ul class=\"fig-list\"><li><code>audience : DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement : DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel : PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType : DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength : PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess : DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>didNumber : PositiveInteger [0..1]</code>: 16-Bit DID-Nummer.\n</li><li><code>fixedLength : Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle : DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType : DiagnosticRoutineTypeEnum</code>: Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li><li><code>ridNumber : PositiveInteger [0..1]</code>: 16-Bit Routine-Identifier (RID).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>didNumber : PositiveInteger [0..1]</code>: 16-Bit DID für die E/A-Steuerung.\n</li><li><code>freezeCurrentStateSupported : Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported : Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported : Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Referenz auf <code>DiagnosticValueNeeds</code> zur Abfrage des aktuellen E/A-Istwerts.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Belange der Diagnose-Kommunikationssicherheit.\n</li><li><strong><code>DiagnosticComponentNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für komponentenbezogene Diagnoseanforderungen.\n</li><li><strong><code>DiagnosticResponseOnEventNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für ereignisgesteuerte Diagnoseantworten (UDS 0x86 ResponseOnEvent).\n</li><li><strong><code>DiagnosticControlNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für übergeordnete Diagnosesteuerungsfunktionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: Literale <code>development</code>, <code>manufacturing</code>, <code>afterSales</code>, <code>supplier</code>, <code>aftermarket</code>.\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: Literale <code>synchronous</code>, <code>asynchronous</code>.\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: Literale <code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>.\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: Literale <code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>.\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: Literale <code>requestCallbackTypeManufacturer</code>, <code>requestCallbackTypeSupplier</code>.\n</li><li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Literale <code>apiUse</code>, <code>observer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}, {"id": "FIG-9ab397f7f05fe661", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 1</code> genau eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für diagnosebezogene Servicebedarfe.\n<ul class=\"fig-list\"><li><code>audience: DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement: DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel: PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType: DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength: PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess: DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>didNumber: PositiveInteger [0..1]</code>: 16-Bit DID-Nummer.\n</li><li><code>fixedLength: Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle: DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType: DiagnosticRoutineTypeEnum</code>: Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li><li><code>ridNumber: PositiveInteger [0..1]</code>: 16-Bit Routine-Identifier (RID).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>didNumber: PositiveInteger [0..1]</code>: 16-Bit DID für die E/A-Steuerung.\n</li><li><code>freezeCurrentStateSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported: Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Referenz auf <code>DiagnosticValueNeeds</code> zur Abfrage des aktuellen E/A-Istwerts.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Belange der Diagnose-Kommunikationssicherheit.\n</li><li><strong><code>DiagnosticComponentNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für komponentenbezogene Diagnoseanforderungen.\n</li><li><strong><code>DiagnosticResponseOnEventNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für ereignisgesteuerte Diagnoseantworten (UDS 0x86 ResponseOnEvent).\n</li><li><strong><code>DiagnosticControlNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für übergeordnete Diagnosesteuerungsfunktionen.\n</li><li><strong><code>DiagnosticRequestFileTransferNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für dateitransferbezogene Diagnoseanforderungen (UDS 0x38 RequestFileTransfer).\n</li></ul>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: Literale <code>development</code>, <code>manufacturing</code>, <code>afterSales</code>, <code>supplier</code>, <code>aftermarket</code>.\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: Literale <code>synchronous</code>, <code>asynchronous</code>.\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: Literale <code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>.\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: Literale <code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>.\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: Literale <code>requestCallbackTypeManufacturer</code>, <code>requestCallbackTypeSupplier</code>.\n</li><li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Literale <code>apiUse</code>, <code>observer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}, {"id": "FIG-b7f27aa861ce82ef", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 0..1</code> optional eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für diagnosebezogene Servicebedarfe.\n<ul class=\"fig-list\"><li><code>audience: DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement: DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel: PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType: DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength: PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess: DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>didNumber: PositiveInteger [0..1]</code>: 16-Bit DID-Nummer.\n</li><li><code>fixedLength: Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle: DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType: DiagnosticRoutineTypeEnum [0..1]</code>: Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li><li><code>ridNumber: PositiveInteger [0..1]</code>: 16-Bit Routine-Identifier (RID).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>didNumber: PositiveInteger [0..1]</code>: 16-Bit DID für die E/A-Steuerung.\n</li><li><code>freezeCurrentStateSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported: Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Referenz auf <code>DiagnosticValueNeeds</code> zur Abfrage des aktuellen E/A-Istwerts.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Belange der Diagnose-Kommunikationssicherheit.\n</li><li><strong><code>DiagnosticComponentNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für komponentenbezogene Diagnoseanforderungen.\n</li><li><strong><code>DiagnosticResponseOnEventNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für ereignisgesteuerte Diagnoseantworten (UDS 0x86 ResponseOnEvent).\n</li><li><strong><code>DiagnosticControlNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für übergeordnete Diagnosesteuerungsfunktionen.\n</li><li><strong><code>DiagnosticRequestFileTransferNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für dateitransferbezogene Diagnoseanforderungen (UDS 0x38 RequestFileTransfer).\n</li></ul>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: Literale <code>development</code>, <code>manufacturing</code>, <code>afterSales</code>, <code>supplier</code>, <code>aftermarket</code>.\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: Literale <code>synchronous</code>, <code>asynchronous</code>.\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: Literale <code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>.\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: Literale <code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>.\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: Literale <code>requestCallbackTypeManufacturer</code>, <code>requestCallbackTypeSupplier</code>.\n</li><li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Literale <code>apiUse</code>, <code>observer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}, {"id": "FIG-a1a4d29aa7892e41", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 0..1</code> optional eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für diagnosebezogene Servicebedarfe.\n<ul class=\"fig-list\"><li><code>audience: DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement: DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel: PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType: DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength: PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess: DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>fixedLength: Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle: DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType: DiagnosticRoutineTypeEnum [0..1]</code>: Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>freezeCurrentStateSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported: Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Referenz auf <code>DiagnosticValueNeeds</code> zur Abfrage des aktuellen E/A-Istwerts.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Belange der Diagnose-Kommunikationssicherheit.\n</li><li><strong><code>DiagnosticComponentNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für komponentenbezogene Diagnoseanforderungen.\n</li><li><strong><code>DiagnosticControlNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für übergeordnete Diagnosesteuerungsfunktionen.\n</li><li><strong><code>DiagnosticRequestFileTransferNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für dateitransferbezogene Diagnoseanforderungen (UDS 0x38 RequestFileTransfer).\n</li></ul>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: Literale <code>development</code>, <code>manufacturing</code>, <code>afterSales</code>, <code>supplier</code>, <code>aftermarket</code>.\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: Literale <code>synchronous</code>, <code>asynchronous</code>.\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: Literale <code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>.\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: Literale <code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>.\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: Literale <code>requestCallbackTypeManufacturer</code>, <code>requestCallbackTypeSupplier</code>.\n</li><li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Literale <code>apiUse</code>, <code>observer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}, {"id": "FIG-3332573e50382d5f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 0..1</code> optional eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für diagnosebezogene Servicebedarfe.\n<ul class=\"fig-list\"><li><code>audience: DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement: DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel: PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType: DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength: PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess: DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>fixedLength: Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle: DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType: DiagnosticRoutineTypeEnum [0..1]</code>: Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>freezeCurrentStateSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported: Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Referenz auf <code>DiagnosticValueNeeds</code> zur Abfrage des aktuellen E/A-Istwerts.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Belange der Diagnose-Kommunikationssicherheit.\n</li><li><strong><code>DiagnosticComponentNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für komponentenbezogene Diagnoseanforderungen.\n</li><li><strong><code>DiagnosticControlNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für übergeordnete Diagnosesteuerungsfunktionen.\n</li><li><strong><code>DiagnosticRequestFileTransferNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für dateitransferbezogene Diagnoseanforderungen (UDS 0x38 RequestFileTransfer).\n</li></ul>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: Literale <code>development</code>, <code>manufacturing</code>, <code>afterSales</code>, <code>supplier</code>, <code>aftermarket</code>.\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: Literale <code>synchronous</code>, <code>asynchronous</code>.\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: Literale <code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>.\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: Literale <code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>.\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: Literale <code>requestCallbackTypeManufacturer</code>, <code>requestCallbackTypeSupplier</code>.\n</li><li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Literale <code>apiUse</code>, <code>observer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}, {"id": "FIG-e6f6337ea70ef52e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2-Metamodell-Klassendiagramm (AUTOSAR M2-Ebene, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Spezifikation diagnosebezogener Servicebedarfe (<code>ServiceNeeds</code>) einer Software-Komponente (SWC) gegenüber den BSW-Modulen <code>Dcm</code> (Diagnostic Communication Manager) und <code>Dem</code> (Diagnostic Event Manager).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formaler Kontrakt zwischen Applikationsschicht und BSW. Generatoren für RTE und BSW-Konfiguration (Dcm/Dem) nutzen diese Metadaten zur automatischen Ableitung von Port-Schnittstellen (Client-Server / Sender-Receiver) sowie zur Konfiguration diagnostischer Dienste (UDS Services 0x22, 0x2E, 0x2F, 0x31, 0x27).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis- und Aggregationsstruktur</h5>\n<ul class=\"fig-list\"><li><strong><code>SwcServiceDependency</code></strong> (Stereotypen: <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Bildet den Anker innerhalb der SWC-Beschreibung und bindet über die Komposition <code>+serviceNeeds 0..1</code> optional eine Instanz von <code>ServiceNeeds</code>.\n</li><li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>): Generische Basisklasse für funktionale BSW-Dienstbedarfe.\n</li><li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, spezialisiert <code>ServiceNeeds</code>): Zentrale Abstraktionsklasse für diagnosebezogene Servicebedarfe.\n<ul class=\"fig-list\"><li><code>audience: DiagnosticAudienceEnum [0..*]</code>: Adressatenkreis für den Servicezugriff.\n</li><li><code>diagRequirement: DiagRequirementIdString [0..1]</code>: Eindeutige Trace-ID zur Spezifikation/Diagnose-Anforderung.\n</li><li><code>securityAccessLevel: PositiveInteger [0..1]</code>: Erforderliche Sicherheitsstufe (UDS 0x27 SecurityAccess).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierte ServiceNeeds-Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticCommunicationManagerNeeds</code></strong>: Spezifiziert allgemeine Service-Callbacks des Dcm.\n<ul class=\"fig-list\"><li><code>serviceRequestCallbackType: DiagnosticServiceRequestCallbackTypeEnum [0..1]</code>: Differenziert Callback-Zuständigkeit (<code>requestCallbackTypeManufacturer</code> vs. <code>requestCallbackTypeSupplier</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticValueNeeds</code></strong>: Definiert Datenzugriffe auf Diagnose-Identifier (UDS 0x22 ReadDataByIdentifier / 0x2E WriteDataByIdentifier).\n<ul class=\"fig-list\"><li><code>dataLength: PositiveInteger [0..1]</code>: Nutzdatenlänge in Byte.\n</li><li><code>diagnosticValueAccess: DiagnosticValueAccessEnum [0..1]</code>: Zugriffsmodus (<code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>).\n</li><li><code>fixedLength: Boolean [0..1]</code>: Feste vs. variable Datenlänge.\n</li><li><code>processingStyle: DiagnosticProcessingStyleEnum [0..1]</code>: Ausführungsmodell (<code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticRoutineNeeds</code></strong>: Definiert Routinensteuerung (UDS 0x31 RoutineControl).\n<ul class=\"fig-list\"><li><code>diagRoutineType: DiagnosticRoutineTypeEnum [0..1]</code>: Ausführungsart (<code>synchronous</code>, <code>asynchronous</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticIoControlNeeds</code></strong>: Definiert I/O-Hardware- bzw. Signalbeeinflussung (UDS 0x2F InputOutputControlByIdentifier).\n<ul class=\"fig-list\"><li><code>freezeCurrentStateSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>FreezeCurrentState</code>.\n</li><li><code>resetToDefaultSupported: Boolean [0..1]</code>: Unterstützung für Parameter <code>ResetToDefault</code>.\n</li><li><code>shortTermAdjustmentSupported: Boolean [0..1]</code>: Unterstützung für temporäre Stellwertvorgabe.\n</li><li><strong>Assoziation <code>+currentValue 0..1</code></strong>: Unidirektionale Referenz auf <code>DiagnosticValueNeeds</code> zur Abfrage des aktuellen E/A-Istwerts.\n</li></ul>\n</li><li><strong><code>DiagnosticsCommunicationSecurityNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Belange der Diagnose-Kommunikationssicherheit.\n</li><li><strong><code>DiagnosticComponentNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für komponentenbezogene Diagnoseanforderungen.\n</li><li><strong><code>DiagnosticControlNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für übergeordnete Diagnosesteuerungsfunktionen.\n</li><li><strong><code>DiagnosticUploadDownloadNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für Upload- und Download-Diagnosedienste (UDS 0x34 / 0x35 / 0x36 / 0x37).\n</li><li><strong><code>DiagnosticRequestFileTransferNeeds</code></strong>: Spezialisiert <code>DiagnosticCapabilityElement</code> für dateitransferbezogene Diagnoseanforderungen (UDS 0x38 RequestFileTransfer).\n</li></ul>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticAudienceEnum</code></strong>: Literale <code>development</code>, <code>manufacturing</code>, <code>afterSales</code>, <code>supplier</code>, <code>aftermarket</code>.\n</li><li><strong><code>DiagnosticRoutineTypeEnum</code></strong>: Literale <code>synchronous</code>, <code>asynchronous</code>.\n</li><li><strong><code>DiagnosticValueAccessEnum</code></strong>: Literale <code>readOnly</code>, <code>readWrite</code>, <code>writeOnly</code>.\n</li><li><strong><code>DiagnosticProcessingStyleEnum</code></strong>: Literale <code>processingStyleSynchronous</code>, <code>processingStyleAsynchronous</code>, <code>processingStyleAsynchronousWithError</code>.\n</li><li><strong><code>DiagnosticServiceRequestCallbackTypeEnum</code></strong>: Literale <code>requestCallbackTypeManufacturer</code>, <code>requestCallbackTypeSupplier</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich das Klassendiagramm statische M2-Metadaten beschreibt, erzwingen die Attribute spezifische BSW- und RTE-Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>UDS-Anfrageprüfung (Dcm):</strong> Bei Eintreffen eines Diagnose-Requests (0x22, 0x2E, 0x2F, 0x31) validiert der Dcm den aktuellen Session-Status gegen <code>audience</code> und die Sicherheitsstufe gegen <code>securityAccessLevel</code>. Bei Nichtübereinstimmung erfolgt NRC <code>0x33</code> (SecurityAccessDenied) oder NRC <code>0x31</code> (RequestOutOfRange).\n</li><li><strong>Synchroner Pfad (<code>processingStyleSynchronous</code> / <code>synchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm blockiert bzw. führt den Aufruf im selben Task-Zyklus über die RTE aus (<code>Rte_Call_&lt;Port&gt;_&lt;Operation&gt;</code>).\n</li><li>SWC-Runnable liefert Rückgabewert (<code>E_OK</code>, <code>E_NOT_OK</code>) direkt zurück.\n</li></ul>\n</li><li><strong>Asynchroner Pfad (<code>processingStyleAsynchronous</code> / <code>asynchronous</code>):</strong>\n<ul class=\"fig-list\"><li>Dcm setzt den Request ab; SWC antwortet initial mit <code>DCM_E_PENDING</code>.\n</li><li>Entkopplung: Dcm pollt das Ergebnis in Folgezyklen via <code>Rte_Result</code> oder empfängt eine Benachrichtigung nach Fertigstellung. Zeitüberwachung über Dcm-P2/P2*-Timer.\n</li></ul>\n</li><li><strong>I/O-Control-Rücklesung:</strong> Fordert der Tester Statusinformationen nach einer E/A-Manipulation an, delegiert der Dcm die Ermittlung an das per <code>+currentValue</code> verknüpfte <code>DiagnosticValueNeeds</code>-Element.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Generierung (RTE-Vertrag):</strong> \n<ul class=\"fig-list\"><li>Ein <code>DiagnosticValueNeeds</code> führt zur automatisierten Erzeugung von Client-Server-Ports mit <code>DataServices_&lt;DID&gt;</code>-Schnittstellen (Operations: <code>ReadData</code>, <code>WriteData</code>).\n</li><li><code>fixedLength = false</code> erfordert in der C-Signatur der Server-Operation zwingend einen variablen Längenparameter (<code>OpStatusType</code>, <code>uint16* DataLength</code>).\n</li></ul>\n</li><li><strong>Konfigurations-Synergie (Dcm-BAM / Upstream-Mapping):</strong> Die Attribute <code>didNumber</code>, <code>ridNumber</code>, <code>securityAccessLevel</code> und <code>dataLength</code> müssen bit-genau mit der Diagnose-Spezifikation (ODX/CDD) übereinstimmen. Fehlende Parameter führen zu unvollständigen BSW-Beschreibungen (<code>DcmDspData</code>, <code>DcmDspRoutine</code>).\n</li><li><strong>Zyklen-Mapping (Dem):</strong> <code>DiagnosticOperationCycleNeeds</code> weist das BSW an, Zyklenzustände bereitzustellen (<code>Dem_SetOperationCycleState</code>). Wird <code>operationCycleAutostart = false</code> gewählt, muss die Applikation den Zyklus explizit per BSW-API ansteuern.\n</li><li><strong>Stack-Einschränkung:</strong> Asynchrone Routinen (<code>DiagnosticRoutineTypeEnum = asynchronous</code>) erfordern in der SWC die Unterstützung des Parameters <code>Dcm_OpStatusType</code> (<code>DCM_INITIAL</code>, <code>DCM_PENDING</code>, <code>DCM_CANCEL</code>), um Abbruchbedingungen durch den Dcm (z. B. Session-Timeout) deterministisch zu behandeln.\n</li></ul>"}], "trans": [{"from": "FIG-2927b70a15a43c20", "to": "FIG-ff3df9b5a95f3967", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticOperationCycleNeeds</code>: Klasse mit den Attributen <code>operationCycle</code>, <code>operationCycleAutomaticEnd</code> und <code>operationCycleAutostart</code> entfernt.\n</li><li><code>OperationCycleTypeEnum</code>: Enumeration mit den Literalen <code>ignition</code>, <code>obdDcy</code>, <code>warmup</code>, <code>power</code>, <code>time</code>, <code>other</code> entfernt.\n</li><li><code>DiagnosticComponentNeeds</code>: Neue Spezialisierung von <code>DiagnosticCapabilityElement</code> ohne Attribute hinzugefügt.\n</li><li><code>DiagnosticResponseOnEventNeeds</code>: Neue Spezialisierung von <code>DiagnosticCapabilityElement</code> ohne Attribute hinzugefügt.\n</li><li><code>DiagnosticControlNeeds</code>: Neue Spezialisierung von <code>DiagnosticCapabilityElement</code> ohne Attribute hinzugefügt.\n</li><li><code>DiagnosticProcessingStyleEnum</code>: Aufzählungsliteral <code>processingStyleAsynchronousWithError</code> ergänzt.\n</li></ul>"}, {"from": "FIG-ff3df9b5a95f3967", "to": "FIG-9ab397f7f05fe661", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticRequestFileTransferNeeds</code>: Neue Spezialisierung von <code>DiagnosticCapabilityElement</code> ohne Attribute hinzugefügt.\n</li></ul>"}, {"from": "FIG-9ab397f7f05fe661", "to": "FIG-b7f27aa861ce82ef", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SwcServiceDependency</code>: Multiplizität der Komposition <code>serviceNeeds</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><code>DiagnosticRoutineNeeds</code>: Multiplizität des Attributs <code>diagRoutineType</code> von obligatorisch (<code>1</code>) auf optional (<code>[0..1]</code>) geändert.\n</li><li>Diagrammlayout: Aufzählungstypen (<code>«enumeration»</code>) von der unteren Diagrammhälfte an den rechten Rand umgruppiert.\n</li></ul>"}, {"from": "FIG-b7f27aa861ce82ef", "to": "FIG-a1a4d29aa7892e41", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticResponseOnEventNeeds</code>: Spezialisierungsklasse von <code>DiagnosticCapabilityElement</code> entfernt.\n</li><li><code>DiagnosticValueNeeds</code>: Attribut <code>didNumber: PositiveInteger [0..1]</code> entfernt.\n</li><li><code>DiagnosticRoutineNeeds</code>: Attribut <code>ridNumber: PositiveInteger [0..1]</code> entfernt.\n</li><li><code>DiagnosticIoControlNeeds</code>: Attribut <code>didNumber: PositiveInteger [0..1]</code> entfernt.\n</li><li>Diagrammlayout: <code>DiagnosticCapabilityElement</code> zentral angeordnet; abgeleitete Klassen links und rechts aufgeteilt.\n</li></ul>"}, {"from": "FIG-a1a4d29aa7892e41", "to": "FIG-3332573e50382d5f", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>DiagnosticAudienceEnum</code>, <code>DiagnosticRoutineTypeEnum</code>, <code>DiagnosticValueAccessEnum</code>, <code>DiagnosticProcessingStyleEnum</code>, <code>DiagnosticServiceRequestCallbackTypeEnum</code>, <code>ObdRatioConnectionKindEnum</code>: Schlüsselwort bzw. Kompartiment-Bezeichner <code>literals</code> in allen Enumerationsblöcken ergänzt.\n</li></ul>"}, {"from": "FIG-3332573e50382d5f", "to": "FIG-e6f6337ea70ef52e", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticUploadDownloadNeeds</code>: Neue Spezialisierung von <code>DiagnosticCapabilityElement</code> hinzugefügt.\n</li><li><code>ObdRatioConnectionKindEnum</code>: Enumeration mit den Literalen <code>apiUse</code> und <code>observer</code> aus dem Diagramm entfernt.\n</li><li><code>DiagnosticRoutineNeeds</code>: Im Layout von der rechten auf die linke Seite verschoben.\n</li><li><code>DiagnosticsCommunicationSecurityNeeds</code>: Im Layout von der linken auf die rechte Seite verschoben.\n</li></ul>"}]};
